"""Source-scoped upgrade logs, support integration and optional local budgets."""
from pathlib import Path
import json,re
ROOT=Path(__file__).resolve().parents[1]
D=json.loads((ROOT/'data/pokebonk-progression-reference.json').read_text(encoding='utf8'))
R=json.loads((ROOT/'data/pokebonk-tools-reference.json').read_text(encoding='utf8'))

def apply_progression(ctx):
 P,pages,section,ref,ext=(ctx[k] for k in ['P','PAGES','section','ref','ext'])
 def add(slug,id,title,body):
  p=pages[P+slug+'/'];s=p['html'];existing=[int(n)for n,body in re.findall(r'<li id="source-(\d+)">(.*?)</li>',s,re.S)if D['client']in body]
  n=existing[0]if existing else max(map(int,re.findall(r'id="source-(\d+)"',s)))+1
  if not existing:
   i=s.index('</ol>',s.index('<section class="sources"'))
   s=s[:i]+f'<li id="source-{n}">'+ext(D['client'],'pokebonk.com — original v0.8.76 client')+' — Checked October 29, 2026. Upgrade-card arithmetic and runtime templates; SINGLE_SOURCE. Source arithmetic checks are not gameplay, final damage or a completed run.</li>'+s[i:]
  s=s.replace('<section class="sources"',section(id,title,body+ref(n))+'<section class="sources"',1)
  p['html']=s.replace('<strong>On this page</strong>','<strong>On this page</strong>'+f'<a href="#{id}">{title}</a>',1)
 add('build-planner','level-plan','Record move levels and offered upgrade cards','''<p>Choose moves above, then expand a move to enter its level and the effects offered by each observed or hypothetical upgrade card. A level alone does not determine the complete result: cards choose distinct random effects. Incomplete cards count only the guaranteed level increment.</p><div id="level-editors"></div><div id="level-result" role="region" aria-label="Move level calculations"></div><div class="progression-grid"><label>Fusion ingredient A <select id="fusion-a"></select></label><label>Fusion ingredient B <select id="fusion-b"></select></label><label>Declared formed stage <select id="fusion-stage"></select></label></div><p id="fusion-level-status" role="status"></p><p>Normal moves cap at level 8; TM Case permits 10. Fusion ingredients still each need level 8. Formed fusions cap at ★5, or ★6 with TM Case. The star records an intention; use the <a href="/pokebonk/move-fusions/">recipe finder</a> to verify the pair. Recipe-specific fusion damage is excluded.</p>''')
 add('build-planner','planned-lab','Preview a purchase target without changing owned levels','''<p><a id="plan-lab-open" href="/pokebonk/lab/#calculator">Set targets and balance in the Lab calculator →</a>, then return a copy of this draft. Target prices use the dated 24-upgrade schedule; recheck the actual game before spending.</p><label><input type="checkbox" id="preview-lab"> Preview planned Lab targets in the fixed panel</label><div id="plan-lab-result" role="status"></div><p>Unchecked uses declared owned levels. Checked uses the greater of owned and target for a hypothetical panel, including support capacity. This does not buy an upgrade or change your owned ledger. Selected normal Alpha types and the separate shiny now form one included support group; the shiny doubles its support bonus and Poké Doll scales the group. Lemonade affects support attacks, not the player’s fixed panel.</p>''')
 add('build-planner','build-notebook','Copy the plan and record the next experiment','''<p>Generate a readable summary to share your declared build and its link. Record an attempt only when you have one: this website does not read game results or verify a win.</p><div class="actions"><button id="make-summary" type="button">Generate build summary</button><button id="copy-summary" type="button">Copy summary</button></div><label>Shareable build summary <textarea id="build-summary" readonly rows="10"></textarea></label><p id="summary-status" role="status"></p><h3>Optional private attempt note</h3><div class="progression-grid"><label>Played version <input id="review-version" maxlength="16" placeholder="e.g. 0.8.76"></label><label>Observed result <select id="review-result"><option value="not-recorded">Not recorded</option><option value="died">Died</option><option value="cleared">Cleared</option><option value="quit">Quit / interrupted</option></select></label><label>Elapsed minutes <input id="review-minutes" type="number" min="0" max="1440"></label><label>What ended or limited the attempt? <input id="review-reason" maxlength="140"></label><label>Change one thing next time <input id="review-next" maxlength="140"></label></div><p>Use Save or Replace in the existing draft controls to keep this note locally. Load restores it and A/B compares it. It is included in your exported backup file, but excluded from public planning URLs and the summary above. Avoid personal information. An imported note is a user declaration, not an endorsed result.</p>''')
 add('moves','move-inspector','Inspect a level and its recorded card effects','''<p>The lookup starts from neutral level-1 templates. Select a move here to inspect later levels with explicitly recorded upgrade effects; use the planner for your selected partner’s modifiers.</p><div class="progression-grid"><label>Move <select id="inspect-move"></select></label><label><input id="inspect-tm" type="checkbox"> TM Case cap (10 instead of 8)</label></div><div id="inspect-result" role="status"></div><div id="inspect-editor"></div><p>Cards contain two distinct effects, or three at Epic/Legendary, bounded by the move archetype’s available effects. These controls describe possible cards; they cannot guarantee an offer. Missing effects are not guessed. Random, weather and buff moves need custom runtime interpretation.</p>''')
 # Per-result entry connects the searchable database to the inspector.
 p=pages[P+'moves/'];p['html']=re.sub(r'(<a href="/pokebonk/build-planner/\?[^"<>]*[?&](?:amp;)?m0=([a-z0-9-]+)[^"<>]*">Plan</a>)',lambda m:m[1]+f' <button type="button" data-inspect-level="{m[2]}">Inspect levels</button>',p['html'])
 add('lab','budget-archive','Save targets and continue a draft','''<p>Set owned levels, target levels and Stardust in the calculator above. Save a new local copy, share the budget, or carry it back to the planner. Targets never count as purchases you already own.</p><div class="progression-grid"><label>Attach budget to <select id="budget-plan"><option value="new">New budget-only draft</option></select></label><label>Name for a new saved copy <input id="budget-name" maxlength="60"></label></div><div class="actions"><button type="button" id="budget-return">Continue in planner</button><button type="button" id="budget-save">Save budget copy</button><button type="button" id="budget-share">Create budget link</button></div><label>Budget share URL <input id="budget-link" readonly></label><p id="budget-archive-status" role="status"></p><p>Existing drafts remain intact. A budget-only draft can receive a partner later. Return to the planner to toggle the hypothetical target preview; owned and target levels remain separately declared.</p>''')
 p=pages[P+'privacy/'];p['html']=p['html'].replace('</article>','''<h2>Upgrade logs, Lab targets and private attempt notes</h2><p>Move levels, offered card effects, declared fusion stage, target Lab levels, Stardust balance and hypothetical-preview choice can be encoded in shared URLs. Anyone with those links can read the declarations. Optional attempt notes (played version, result, elapsed time, failure reason and next change) are stored only when you explicitly save a draft, in the existing pb-build-drafts-v1 browser key. Exporting drafts includes these notes in the local backup file; share URLs and generated summaries exclude them. Import and load restore user declarations without verifying gameplay. Delete drafts with the existing controls or clear this site’s storage. No game account, results API or additional remote storage is accessed.</p></article>''',1)
 for slug in ['build-planner','moves','lab']:
  p=pages[P+slug+'/'];p['html']=re.sub(r'<p class="meta">.*?</p>','<p class="meta">Planning tools reviewed October 29, 2026 · Original v0.8.76 upgrade rules · Earlier reference snapshots stay dated</p>',p['html'],count=1,flags=re.S);payload={k:D[k] for k in ['version','arches','rarities','lab']};payload.update(moves=D['moves'] if slug!='lab' else [],alpha=D['alphaTypes'],roles=[{'id':x['id'],'name':x['name']}for x in R['league']])
  p['html']=p['html'].replace('</main>','<script id="progression-data" type="application/json">'+json.dumps(payload,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')+'</script></main>').replace('</head>','<link rel="stylesheet" href="/assets/pokebonk/progression.css"><script src="/assets/pokebonk/progression-math.js" defer></script><script src="/assets/pokebonk/progression.js" defer></script></head>')
 p=pages[P+'build-planner/'];p['html']=p['html'].replace('Alpha bonuses remain a separate support group; condition experiments remain separate from the fixed-panel numeric results.','Alpha bonuses are included as their own group in the fixed panel; condition experiments remain separate.').replace('selected item mods, vitamin levels and fixed passive mods.','selected item mods, vitamin levels, fixed passive mods and declared Alpha support. Planned Lab targets apply only when their preview is checked.').replace('weather, shiny perks, team auras','weather, shiny combat perks, team auras')
 # Existing shared assets have a four-hour cache. Revise exact references everywhere they occur.
 for p in pages.values():
  p['html']=p['html'].replace('compare.js?v=20261028-decisions','compare.js?v=20261029-progression').replace('src="/assets/pokebonk/decisions.js"','src="/assets/pokebonk/decisions.js?v=20261029-progression"').replace('src="/assets/pokebonk/continuity.js"','src="/assets/pokebonk/continuity.js?v=20261029-progression"')
